css:
.buttons {
  display: flex;
  gap: 12px;
  padding: 16px;
  font-family: system-ui, sans-serif;
}

.button {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  border: 2px solid currentColor;
  border-radius: 999px;
  background-color: transparent;
  color: #3f3f46;
  font: inherit;
}

.dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background-color: currentColor;
}

.danger {
  color: #dc2626;
}

.success {
  color: #16a34a;
}
